class Account:
    def __init__(self, balance):
        self.balance = balance

    def calculateInterest(self):
        return 0

class FixedDeposit(Account):
    def __init__(self, balance, interest_rate):
        super().__init__(balance)
        self.interestRate = interest_rate

    def calculateInterest(self):
        return self.balance * self.interestRate // 100

def main():
    balance = int(input())
    interest_rate = int(input())

    # Case 1: Slicing problem with vector<Account>
    # When Derived class object is stored in base class container
    accounts_sliced = [Account(balance)]
    for _ in range(1):
        accounts_sliced.append(FixedDeposit(balance, interest_rate))

    # Convert to base class - slicing occurs
    sliced_accounts = []
    for acc in accounts_sliced:
        sliced_accounts.append(Account(acc.balance))

    sliced_interest = 0
    for acc in sliced_accounts:
        sliced_interest += acc.calculateInterest()

    # Case 2: Correct approach using vector<Account*> (simulated with list of references)
    accounts_ref = []
    accounts_ref.append(Account(balance))
    accounts_ref.append(FixedDeposit(balance, interest_rate))

    correct_interest = 0
    for acc in accounts_ref:
        correct_interest += acc.calculateInterest()

    print(f"Interest (Sliced): {sliced_interest}")
    print(f"Interest (Correct): {correct_interest}")

if __name__ == "__main__":
    main()
